<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';Auth::requireLogin();$pdo=Database::connection();Auth::ensureUserSchema();ensure_member_soft_delete_schema($pdo);$pdo->exec("CREATE TABLE IF NOT EXISTS member_activation_codes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,member_id INT UNSIGNED NOT NULL,code_hash CHAR(64) NOT NULL UNIQUE,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_by_user_id INT UNSIGNED NULL,INDEX idx_mac_member(member_id),INDEX idx_mac_expiry(expires_at),CONSTRAINT fk_mac_member FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$tags=$pdo->query('SELECT t.id,t.name,COUNT(mt.member_id) cnt FROM tags t LEFT JOIN member_tags mt ON mt.tag_id=t.id GROUP BY t.id,t.name ORDER BY t.name')->fetchAll();$rows=[];$tagName='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$tag=(int)($_POST['tag_id']??0);$q=$pdo->prepare('SELECT t.name,m.id,m.first_name,m.last_name,m.weight_kg,m.member_number,u.id user_id FROM member_tags mt JOIN tags t ON t.id=mt.tag_id JOIN members m ON m.id=mt.member_id LEFT JOIN users u ON u.member_id=m.id WHERE mt.tag_id=:tag AND m.deleted_at IS NULL ORDER BY m.last_name,m.first_name');$q->execute(['tag'=>$tag]);$members=$q->fetchAll();if(!$members)throw new RuntimeException('Geen leden gevonden voor deze tag.');$tagName=$members[0]['name'];$alphabet='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';foreach($members as$m){if($m['user_id']){$rows[]=$m+['code'=>'Reeds account'];continue;}$raw='';for($i=0;$i<8;$i++)$raw.=$alphabet[random_int(0,strlen($alphabet)-1)];$code=substr($raw,0,4).'-'.substr($raw,4);$pdo->prepare('UPDATE member_activation_codes SET expires_at=NOW() WHERE member_id=:id AND used_at IS NULL')->execute(['id'=>$m['id']]);$pdo->prepare('INSERT INTO member_activation_codes(member_id,code_hash,expires_at,created_by_user_id) VALUES(:id,:h,DATE_ADD(NOW(),INTERVAL 30 DAY),:uid)')->execute(['id'=>$m['id'],'h'=>hash('sha256',$raw),'uid'=>(int)($_SESSION['user_id']??0)?:null]);$rows[]=$m+['code'=>$code];}}catch(Throwable $e){$err=$e->getMessage();}}
?><!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Activatiecodes | Heli One</title><style>body{font-family:Arial,sans-serif;background:#f5f6f8;margin:0}header{background:#111;color:#fff;padding:18px 28px}main{max-width:1100px;margin:30px auto;padding:0 20px}.card{background:#fff;padding:22px;border-radius:14px;margin:16px 0}.btn{padding:10px 14px;border:0;border-radius:8px;background:#111;color:#fff;font-weight:700;cursor:pointer;text-decoration:none}select{padding:10px;min-width:320px}table{width:100%;border-collapse:collapse;background:#fff}th,td{padding:10px;border-bottom:1px solid #ddd;text-align:left}.code{font-family:monospace;font-size:18px;font-weight:700}.err{background:#feecec;padding:12px}@media print{header,.noprint{display:none}body{background:#fff}main{margin:0;max-width:none}.card{padding:0}table{font-size:12px}}</style></head><body><header>Heli One Members</header><main><h1>Activatiecodes per tag</h1><div class="card noprint"><p>Genereer voor alle leden zonder account onder één tag een persoonlijke eenmalige code. Nieuwe codes vervangen eerdere ongebruikte codes en zijn 30 dagen geldig.</p><?php if($err):?><p class="err"><?=e($err)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><select name="tag_id" required><option value="">Kies tag...</option><?php foreach($tags as$t):?><option value="<?=(int)$t['id']?>"><?=e($t['name'])?> (<?=(int)$t['cnt']?>)</option><?php endforeach;?></select> <button class="btn">Codes genereren</button></form></div><?php if($rows):?><div class="noprint"><button class="btn" onclick="window.print()">Lijst afdrukken / PDF</button></div><div class="card"><h2><?=e($tagName)?></h2><p>Activatie via: <strong>members.heli-one.be/activate.php</strong></p><table><thead><tr><th>Naam</th><th>Voornaam</th><th>Gewicht</th><th>Lidnr.</th><th>Activatiecode</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=e($r['last_name'])?></td><td><?=e($r['first_name'])?></td><td><?=e((string)($r['weight_kg']??''))?></td><td><?=e($r['member_number']??'')?></td><td class="code"><?=e($r['code'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></main></body></html>